import re
with open('main.aux') as f:
    content = f.read()
pages = {}
for match in re.finditer(r'newlabel\{([^}]+)\}\{\{([^}]*)\}\{(\d+)\}', content):
    label, sec, page = match.group(1), match.group(2), int(match.group(3))
    if label.startswith('sec:'):
        pages[label] = page
for k in sorted(pages.keys(), key=lambda x: pages[x]):
    if pages[k] <= 10:
        print(f'  {k}: page {pages[k]}')
